import sys
from operator import itemgetter
N = int(input().strip())

def cross(p, q, r):
	return (p[0] - q[0]) * (r[1] - q[1]) - (p[1] - q[1]) * (r[0] - q[0])

def dist(p1, p2):
	return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2
(U, L) = ([], [])

def Convex_hull(P):
	global U, L
	(U, L) = ([], [])
	sz = len(P)
	for i in range(sz):
		while len(U) >= 2 and cross(U[-2], U[-1], P[i]) <= 0:
			U.pop()
		while len(L) >= 2 and cross(L[-2], L[-1], P[i]) >= 0:
			L.pop()
		L.append(P[i])
		U.append(P[i])

def Find_maximization_pair():
	global U, L
	ans = 0
	(P, Q) = (0, 0)
	sizeU = len(U)
	sizeL = len(L)
	(i, j) = (0, sizeL - 1)
	while 0 < j or i < sizeU - 1:
		tmpdist = dist(U[i], L[j])
		if tmpdist > ans:
			(P, Q, ans) = (i, j, tmpdist)
		if i == sizeU - 1:
			j -= 1
		elif j == 0:
			i += 1
		elif (U[i + 1][1] - U[i][1]) * (L[j][0] - L[j - 1][0]) > (U[i + 1][0] - U[i][0]) * (L[j][1] - L[j - 1][1]):
			i += 1
		else:
			j -= 1
	return ([U[P][2], L[Q][2]], ans)

def log_out(count, value):
	s = str(value) + '\n'
	while count:
		if count % 2:
			sys.stdout.write(s)
		s += s
		count //= 2

def main():
	ans = []
	P = []
	for i in range(1, N + 1):
		s = sys.stdin.readline()
		(x, y) = map(int, s.strip().split())
		P.append((x, y, i))
	P.sort(key=itemgetter(0, 1))
	while len(P) > 1:
		size = len(P)
		Convex_hull(P)
		(res, disT) = Find_maximization_pair()
		maxx = max(res)
		count = size - maxx + 1
		ans.append((count, disT))
		P = list(filter(lambda it: it[2] < maxx, P))
	print(0)
	for it in reversed(ans):
		log_out(it[0], it[1])
main()
